require("addon")

-- Global credentials (can be loaded from account_config.lua or defaulted)
local PASSWORD = ""
local AUTO_LOGIN_ENABLED = true

-- Safely load dynamic account config generated by BotService
local function loadAccountConfig()
    local f = loadfile("scripts/account_config.lua") or loadfile("account_config.lua")
    if f then
        local ok, err = pcall(f)
        if ok then
            if _G.PASSWORD and _G.PASSWORD ~= "" then
                PASSWORD = _G.PASSWORD
            end
            if _G.AUTO_LOGIN_ENABLED ~= nil then
                AUTO_LOGIN_ENABLED = _G.AUTO_LOGIN_ENABLED
            end
        else
            print("[AutoLogin] Config warning: " .. tostring(err))
        end
    end
end
loadAccountConfig()

local hasAttemptedLogin = false
local isLoggedIn = false
local isReconnecting = false
local loginAttempts = 0
local statsLoopActive = false

function onLoad()
    print("[AutoLogin] Script active. Auto-login enabled (Pure Sleep Mode / اسلیپ دائم).")
end

function onDisconnect()
    hasAttemptedLogin = false
    isLoggedIn = false
    isReconnecting = false
    loginAttempts = 0
    statsLoopActive = false
    print("[AutoLogin] Disconnected from server. Session reset.")
end

local function requestStats(delayMs)
    newTask(function()
        if delayMs and delayMs > 0 then
            wait(delayMs)
        end
        if not isReconnecting then
            sendInput("/stats")
        end
    end)
end

local function startStatsLoop()
    if statsLoopActive then return end
    statsLoopActive = true
    newTask(function()
        -- Wait 3.5s after server confirms sleep before first stats request
        wait(3500)
        if not isReconnecting then
            sendInput("/stats")
        end

        -- Periodic refresh every 90 seconds
        while statsLoopActive do
            wait(90000)
            if not isReconnecting then
                sendInput("/stats")
            end
        end
    end)
end

function onPrintLog(text)
    if not text then return end

    local lower = text:lower()

    if lower:find("put to sleep") or lower:find("using raksamp") or lower:find("welcome ") or lower:find("confirmed in sleep mode") or lower:find("you have been spawned") then
        isLoggedIn = true
        print("[AutoLogin] >>> Account confirmed in Sleep Mode (اسلیپ فعال است).")
        startStatsLoop()
    end

    -- If server says dialog is open when command executed, retry in 4s
    if lower:find("can't execute commands when a dialog is shown") or lower:find("dialog is shown up") then
        requestStats(4000)
    end

    -- Reconnect trigger on server kick, disconnect, or notice
    if not isReconnecting then
        local myNick = (getBotNick and getBotNick()) or ""
        local isMyKick = (myNick ~= "" and lower:find(myNick:lower(), 1, true) and lower:find("kicked by admbot", 1, true))
        
        if lower:find("already logged in", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Account already logged in! Waiting 30s before retry to avoid IP ban...")
            newTask(function()
                wait(30000)
                reconnect(5000)
            end)
        elseif lower:find("you are banned", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Temporary IP ban detected. Waiting 60s before retry...")
            newTask(function()
                wait(60000)
                reconnect(5000)
            end)
        elseif lower:find("you have been kicked", 1, true) or isMyKick or lower:find("server closed the connection", 1, true) or lower:find("connection was closed", 1, true) then
            isReconnecting = true
            print("[AutoLogin] Server disconnect/kick detected: " .. text .. ". Waiting 10s before reconnecting...")
            newTask(function()
                wait(10000)
                reconnect(3000)
            end)
        end
    end

    -- Suppress News Reporter SMS ads from printing to console
    if lower:find("/sms") or lower:find("tablighat") or lower:find("pazira hastim") or lower:find("paziraye") or lower:find("nr %[[%w%s_]+%]:") or lower:find("nr:") or lower:find("montasher mikonim") then
        return false
    end
end

function onReceiveRPC(id, bs)
    if id == RPC_ScrDialogBox then
        -- CRITICAL SECURITY PROTECTION:
        -- Once the account is logged into the server, NEVER intercept or auto-answer ANY dialog with password!
        -- This guarantees that in-game dialogs (/report, /helpme, /ad, /pm, bank, admin dialogs, etc.)
        -- can NEVER leak or send the account password under any circumstances.
        if isLoggedIn then
            return
        end

        local wDialogID = bs:readUInt16()
        local bDialogStyle = bs:readUInt8()
        local bTitleLength = bs:readUInt8()
        local szTitle = (bTitleLength and bTitleLength > 0) and bs:readString(bTitleLength) or ""
        local titleLower = (szTitle and szTitle:lower()) or ""

        -- 1. Handle launcher warning or notice dialog (ID 1 or launcher/notice/warning)
        if wDialogID == 1 or titleLower:find("launcher") or titleLower:find("notice") or titleLower:find("warning") then
            print(string.format("[AutoLogin] Notice/Launcher dialog (ID: %d) received. Auto-confirming...", wDialogID))
            newTask(function()
                wait(500)
                sendDialogResponse(wDialogID, 1, 0, "")
            end)
            return false
        end

        -- 2. Handle stats dialog auto-close
        if titleLower:find("stats") or titleLower:find("status") then
            newTask(function()
                wait(500)
                sendDialogResponse(wDialogID, 1, 0, "")
            end)
            return false
        end

        -- 3. Check for login dialog ONLY before login:
        -- Must explicitly contain login / password / ورود / رمز in the title.
        -- NEVER match random dialog IDs or dialog style without title verification.
        local isLoginTitle = titleLower:find("login") or titleLower:find("password") or titleLower:find("ramz") or titleLower:find("رمز") or titleLower:find("ورود")
        local isLoginDialog = not isLoggedIn and isLoginTitle and (bDialogStyle == 3 or bDialogStyle == 1 or wDialogID == 2 or wDialogID == 3)

        if isLoginDialog and AUTO_LOGIN_ENABLED and PASSWORD ~= "" then
            if loginAttempts < 2 then
                loginAttempts = loginAttempts + 1
                hasAttemptedLogin = true
                print(string.format("[AutoLogin] Login dialog (ID: %d, Attempt: %d) detected. Automatically sending password...", wDialogID, loginAttempts))

                newTask(function()
                    wait(600)
                    sendDialogResponse(wDialogID, 1, 0, PASSWORD)
                    print("[AutoLogin] Password submitted successfully. Bot will remain in Sleep Mode (بدون اسپاون).")

                    -- Backup stats request after login sequence completes (15s)
                    requestStats(15000)
                end)
                return false
            else
                print("[AutoLogin] ⚠️ خطا: پسورد ارسال شد اما سرور مجدداً درخواست رمز کرد. لطفاً صحت رمز عبور را بررسی نمایید.")
                return false
            end
        end
    end
end
